-- Current application deletion/retained-evidence contract, checked after migrations on every release.
SELECT CASE WHEN
  EXISTS (SELECT 1 FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME='trg_dcc_reg_cert_master_immutable_bu' AND BINARY REGEXP_REPLACE(ACTION_STATEMENT,'[[:space:]`]+','')=X'')
  AND EXISTS (SELECT 1 FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME='trg_dcc_reg_cert_snapshot_immutable_bu' AND BINARY REGEXP_REPLACE(ACTION_STATEMENT,'[[:space:]`]+','')=X'')
  AND EXISTS (SELECT 1 FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME='trg_dcc_reg_cert_master_immutable_bd' AND BINARY REGEXP_REPLACE(ACTION_STATEMENT,'[[:space:]`]+','')=X'424547494e49464f4c442e7374617475733c3e274452414654275448454e5349474e414c53514c5354415445273435303030275345544d4553534147455f544558543d27466f726d616c726567697374726174696f6e63657274696669636174656d617374657263616e6e6f74626564656c65746564273b454e4449463b454e44')
  AND EXISTS (SELECT 1 FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME='trg_dcc_reg_cert_audit_immutable_bu' AND BINARY REGEXP_REPLACE(ACTION_STATEMENT,'[[:space:]`]+','')=X'424547494e5349474e414c53514c5354415445273435303030275345544d4553534147455f544558543d27526567697374726174696f6e636572746966696361746561756469746973617070656e642d6f6e6c79273b454e44')
  AND EXISTS (SELECT 1 FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA=DATABASE() AND TRIGGER_NAME='trg_dcc_reg_cert_audit_immutable_bd' AND BINARY REGEXP_REPLACE(ACTION_STATEMENT,'[[:space:]`]+','')=X'424547494e5349474e414c53514c5354415445273435303030275345544d4553534147455f544558543d27526567697374726174696f6e6365727469666963617465617564697463616e6e6f74626564656c65746564273b454e44')
  AND (SELECT GROUP_CONCAT(COLUMN_NAME ORDER BY SEQ_IN_INDEX) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='dcc_registration_certificate_audit' AND INDEX_NAME='uk_dcc_reg_cert_audit_event' AND NON_UNIQUE=0)='tenant_id,event_key'
THEN 'DATABASE_CONTRACT_PASS:dcc-certificate-retained-delete'
ELSE 'DATABASE_CONTRACT_FAIL:dcc-certificate-retained-delete' END;
